style.css:
/* Applique un fond personnalisé pour Roblox */
body {
  background-image: url("https://i.imgur.com/XXXXXX.jpg"); /* Remplacez par l'URL de ton image */
  background-size: cover; /* L'image couvre tout l'écran */
  background-attachment: fixed; /* L'image reste fixe au scroll */
  background-repeat: no-repeat; /* L'image ne se répète pas */
  background-position: center; /* Centre l'image */
  margin: 0;
  padding: 0;
}

/* Adapte le texte pour plus de lisibilité */
body, p, h1, h2, h3, h4, h5, h6, a {
  color: white !important;
  font-family: Arial, sans-serif; /* Choisit une police lisible */
}

/* Supprime les arrières-plans d'autres éléments */
div, header, footer, nav {
  background: transparent !important;
}

/* S'assure que les liens sont visibles et élégants */
a {
  text-decoration: none; /* Retire le soulignement des liens */
  color: #ffffff !important; /* Applique une couleur blanche aux liens */
}

a:hover {
  color: #ffcc00 !important; /* Change la couleur des liens au survol */
}

/* Évite que des éléments dépassent du fond */
html, body {
  height: 100%;   height: 100%;
}
